module autograde_alu4;
reg [3:0] A, B; reg [1:0] OP;
wire [3:0] Result; wire C, V, Z, N;
reg [3:0] expected_result; reg expected_c, expected_v;
integer passed, failed;
ALU4 dut(Result, C, V, Z, N, A, B, OP);

task check;
  input integer id; input [3:0] testA; input [3:0] testB; input [1:0] testOp; input checkCV;
  reg [4:0] addRes;
  begin
    A = testA; B = testB; OP = testOp;
    case (testOp)
      2'b00: begin addRes = testA + testB; expected_result = addRes[3:0]; expected_c = addRes[4];
                    expected_v = (~(testA[3]^testB[3])) & (expected_result[3]^testA[3]); end
      2'b01: begin addRes = testA + (~testB & 4'hF) + 1'b1; expected_result = addRes[3:0]; expected_c = addRes[4];
                    expected_v = (testA[3]^testB[3]) & (expected_result[3]^testA[3]); end
      2'b10: begin expected_result = testA & testB; expected_c = 1'bx; expected_v = 1'bx; end
      2'b11: begin expected_result = testA ^ testB; expected_c = 1'bx; expected_v = 1'bx; end
    endcase
    #1;
    if (Result !== expected_result) begin
      $display("TEST|ALU4|%0d|FAIL|Result mismatch: A=%b B=%b OP=%b expected=%b got=%b", id,A,B,OP,expected_result,Result);
      failed = failed + 1;
    end else if (Z !== (expected_result == 4'b0000)) begin
      $display("TEST|ALU4|%0d|FAIL|Z flag wrong: expected=%b got=%b", id, (expected_result==4'b0000), Z);
      failed = failed + 1;
    end else if (N !== expected_result[3]) begin
      $display("TEST|ALU4|%0d|FAIL|N flag wrong: expected=%b got=%b", id, expected_result[3], N);
      failed = failed + 1;
    end else if (checkCV && (C !== expected_c || V !== expected_v)) begin
      $display("TEST|ALU4|%0d|FAIL|C/V wrong: expectedC=%b expectedV=%b gotC=%b gotV=%b", id,expected_c,expected_v,C,V);
      failed = failed + 1;
    end else begin
      $display("TEST|ALU4|%0d|PASS", id);
      passed = passed + 1;
    end
  end
endtask

initial begin
  passed = 0; failed = 0;
  check(1, 4'd3, 4'd2, 2'b00, 1);
  check(2, 4'd7, 4'd1, 2'b00, 1);
  check(3, 4'hF, 4'h1, 2'b00, 1);
  check(4, 4'd5, 4'd3, 2'b01, 1);
  check(5, 4'd0, 4'd1, 2'b01, 1);
  check(6, 4'b1000, 4'b0001, 2'b01, 1);
  check(7, 4'd5, 4'd3, 2'b10, 0);
  check(8, 4'd0, 4'd7, 2'b10, 0);
  check(9, 4'd5, 4'd3, 2'b11, 0);
  check(10, 4'd5, 4'd5, 2'b11, 0);
  check(11, 4'd3, 4'd5, 2'b01, 1);

  if (failed == 0) $display("RESULT|ALU4|PASS|%0d/11", passed);
  else $display("RESULT|ALU4|FAIL|%0d/11", passed);
  $finish;
end
endmodule

