module mealy(clk, rst, inp, outp);
input clk, rst, inp;
output outp;
reg [1:0] state;
reg outp;

always @ (posedge clk, posedge rst) begin
  if (rst) begin
    state <= 2'b00;
    outp <= 0;
  end else begin
    case (state)
      2'b00: if (inp) begin state <= 2'b01; outp <= 0; end
             else      begin state <= 2'b10; outp <= 0; end
      2'b01: if (inp) begin state <= 2'b00; outp <= 1; end
             else      begin state <= 2'b10; outp <= 0; end
      2'b10: if (inp) begin state <= 2'b01; outp <= 0; end
             else      begin state <= 2'b00; outp <= 1; end
      default: begin state <= 2'b00; outp <= 0; end
    endcase
  end
end
endmodule

